:is([data-phase="hero"]) :is([class*="composerStack"], [class*="heroWorkspaceRow"], [class*="workspaceLabel"], [class*="seatLabel"], [class*="triggerLabel"]),
body:not([data-dsh-conversation-content]) :is([class*="composerStack"], [class*="heroWorkspaceRow"]) {
